CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, parent_id TEXT REFERENCES departments(id));
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), department_id TEXT REFERENCES departments(id), manager_id TEXT REFERENCES users(id), email TEXT NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', active BIGINT NOT NULL DEFAULT 1, created_at BIGINT NOT NULL, UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS oidc_states (id TEXT PRIMARY KEY, verifier TEXT NOT NULL, nonce TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS spaces (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT 'book', color TEXT NOT NULL DEFAULT 'blue', created_by TEXT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS grants (id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), principal_type TEXT NOT NULL, principal_id TEXT NOT NULL, include_descendants BIGINT NOT NULL DEFAULT 0, can_view BIGINT NOT NULL DEFAULT 0, can_create BIGINT NOT NULL DEFAULT 0, can_manage BIGINT NOT NULL DEFAULT 0, effect TEXT NOT NULL DEFAULT 'allow', UNIQUE(space_id,principal_type,principal_id));
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), space_id TEXT NOT NULL REFERENCES spaces(id), title TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, storage_key TEXT NOT NULL, size BIGINT NOT NULL, checksum TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 1, indexed_version BIGINT, status TEXT NOT NULL DEFAULT 'queued', error TEXT, tags TEXT NOT NULL DEFAULT '[]', created_by TEXT NOT NULL REFERENCES users(id), deleted BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS document_versions (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), version BIGINT NOT NULL, storage_key TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, checksum TEXT NOT NULL, size BIGINT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at BIGINT NOT NULL, UNIQUE(document_id,version));
CREATE TABLE IF NOT EXISTS chunks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), space_id TEXT NOT NULL REFERENCES spaces(id), document_id TEXT NOT NULL REFERENCES documents(id), version BIGINT NOT NULL, text TEXT NOT NULL, search_tokens TEXT NOT NULL, page BIGINT NOT NULL, kind TEXT NOT NULL, image_key TEXT, position BIGINT NOT NULL, embedding TEXT, embedding_model TEXT);
CREATE TABLE IF NOT EXISTS index_jobs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), document_id TEXT NOT NULL REFERENCES documents(id), version BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts BIGINT NOT NULL DEFAULT 0, worker_token TEXT, lease_until BIGINT, available_at BIGINT NOT NULL, error TEXT, created_at BIGINT NOT NULL, finished_at BIGINT);
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, prefix TEXT NOT NULL, secret_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL, expires_at BIGINT NOT NULL, revoked BIGINT NOT NULL DEFAULT 0, last_used_at BIGINT, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT, action TEXT NOT NULL, resource_id TEXT, details TEXT NOT NULL DEFAULT '{}', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), role TEXT NOT NULL, content TEXT NOT NULL, citations TEXT NOT NULL DEFAULT '[]', created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_departments_tenant ON departments(tenant_id);
CREATE INDEX IF NOT EXISTS ix_users_tenant ON users(tenant_id);
CREATE INDEX IF NOT EXISTS ix_spaces_tenant ON spaces(tenant_id);
CREATE INDEX IF NOT EXISTS ix_grants_space ON grants(space_id);
CREATE INDEX IF NOT EXISTS ix_docs_tenant_space ON documents(tenant_id,space_id,deleted);
CREATE INDEX IF NOT EXISTS ix_chunks_tenant_space ON chunks(tenant_id,space_id);
CREATE INDEX IF NOT EXISTS ix_chunks_document ON chunks(document_id,version);
CREATE INDEX IF NOT EXISTS ix_jobs_status ON index_jobs(status,available_at);
CREATE INDEX IF NOT EXISTS ix_audit_tenant_date ON audit_events(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS ix_attempts_fingerprint ON login_attempts(fingerprint,created_at);
CREATE INDEX IF NOT EXISTS ix_messages_conversation ON messages(conversation_id,created_at);
CREATE TABLE IF NOT EXISTS schema_migrations (version BIGINT PRIMARY KEY, applied_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS tenant_model_configs (tenant_id TEXT PRIMARY KEY REFERENCES tenants(id), payload TEXT NOT NULL, revision BIGINT NOT NULL, updated_at BIGINT NOT NULL);
